#include "exotic/cognition/attention_store.hpp"
#include "exotic/cognition/storage_schema.hpp"
#include <sqlite3.h>
#include <stdexcept>
namespace exotic::cognition {namespace {sqlite3*open_db(const std::string&p){sqlite3*d=nullptr;if(sqlite3_open(p.c_str(),&d)!=SQLITE_OK)throw std::runtime_error("attention store open failed");try{apply_storage_migrations(d);}catch(...){sqlite3_close(d);throw;}return d;}}
std::vector<TopicAttentionState> AttentionStore::load() const{sqlite3*d=open_db(store_.path());sqlite3_stmt*s=nullptr;sqlite3_prepare_v2(d,"SELECT topic_id,last_considered,cooldown_until,repeats_in_window,stopped FROM attention_state",-1,&s,nullptr);std::vector<TopicAttentionState> out;while(sqlite3_step(s)==SQLITE_ROW){out.push_back({reinterpret_cast<const char*>(sqlite3_column_text(s,0)),sqlite3_column_int64(s,1),sqlite3_column_int64(s,2),static_cast<std::uint32_t>(sqlite3_column_int(s,3)),sqlite3_column_int(s,4)!=0});}sqlite3_finalize(s);sqlite3_close(d);return out;}
void AttentionStore::save(const TopicAttentionState&state) const{if(state.topic_id.empty())return;sqlite3*d=open_db(store_.path());sqlite3_stmt*s=nullptr;sqlite3_prepare_v2(d,"INSERT INTO attention_state(topic_id,last_considered,cooldown_until,repeats_in_window,stopped) VALUES(?,?,?,?,?) ON CONFLICT(topic_id) DO UPDATE SET last_considered=excluded.last_considered,cooldown_until=excluded.cooldown_until,repeats_in_window=excluded.repeats_in_window,stopped=excluded.stopped",-1,&s,nullptr);sqlite3_bind_text(s,1,state.topic_id.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s,2,state.last_considered);sqlite3_bind_int64(s,3,state.cooldown_until);sqlite3_bind_int(s,4,static_cast<int>(state.repeats_in_window));sqlite3_bind_int(s,5,state.stopped?1:0);sqlite3_step(s);sqlite3_finalize(s);sqlite3_close(d);}
} // namespace exotic::cognition
